DROP FUNCTION IF EXISTS public.nmis_public_provider_directory(text, text, text, text, integer); CREATE FUNCTION public.nmis_public_provider_directory(p_search text DEFAULT NULL, p_lga text DEFAULT NULL, p_category text DEFAULT NULL, p_service text DEFAULT NULL, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, provider_code text, provider_name text, category text, ownership text, lga text, state text, services text[], address text, latitude double precision, longitude double precision) LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT p.id, p.provider_code, p.provider_name, p.category, p.ownership, p.lga, p.state, COALESCE((SELECT array_agg(ps.service_name ORDER BY ps.service_name) FROM public.provider_services ps WHERE ps.provider_id = p.id), ARRAY[]::text[]), p.address, p.latitude, p.longitude FROM public.providers p WHERE lower(trim(coalesce(p.status, 'active'))) = 'active' AND (nullif(trim(p_search), '') IS NULL OR p.provider_name ILIKE '%' || trim(p_search) || '%' OR p.provider_code ILIKE '%' || trim(p_search) || '%' OR p.lga ILIKE '%' || trim(p_search) || '%') AND (nullif(trim(p_lga), '') IS NULL OR lower(trim(p.lga)) = lower(trim(p_lga))) AND (nullif(trim(p_category), '') IS NULL OR p.category = upper(trim(p_category))) AND (nullif(trim(p_service), '') IS NULL OR EXISTS (SELECT 1 FROM public.provider_services ps WHERE ps.provider_id = p.id AND ps.service_name = p_service)) ORDER BY p.provider_name LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200); $$; GRANT EXECUTE ON FUNCTION public.nmis_public_provider_directory(text, text, text, text, integer) TO anon, authenticated;